source_context:
199:       command: 'list_vms'
200:       uri: '{{ kvm_vm__connect_url }}'
201:     register: 'kvm_vm__virt_info_result'
202:     check_mode: false # run task even if `--check` is specified
203: 
204:   - name: >
205:       virt-install
206:       {% if kvm_vm__boot is defined and kvm_vm__boot | length %}
207:       --boot {{ kvm_vm__boot }}
208:       {% endif %}
209:       {% if kvm_vm__install_location is defined and kvm_vm__install_location | length %}
210:       --location {{ kvm_vm__install_location | quote }}
211:       {% if kvm_vm__install_extra_args | length %}
212:       --extra-args {{ kvm_vm__install_extra_args | quote }}
213:       {% endif %}
214:       --wait {{ kvm_vm__wait }}
215:       {% else %}
216:       --import
217:       {% endif %}
218:       --connect {{ kvm_vm__connect_url }}
219:       --name {{ kvm_vm__name }}
220:       --cpu host-model
221:       --vcpus {{ kvm_vm__vcpus }}
222:       --memory {{ kvm_vm__memory }},maxmemory={{ kvm_vm__max_memory }}
223:       {% if kvm_vm__existing_boot_disk is defined and kvm_vm__existing_boot_disk | length %}
224:       --disk {{ (kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] ~ '/' ~ kvm_vm__existing_boot_disk ~ ',bus=virtio') | quote }}
225:       {% else %}
226:       --disk {{ (kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] ~ '/' ~ kvm_vm__name ~ '-boot.qcow2,bus=virtio') | quote }}
227:       {% endif %}
228:       {% for item in kvm_vm__additional_disks %}
229:       --disk {{ (kvm_vm__pool_info_result["pools"][item["pool"] | d(kvm_vm__pool)]["path"] ~ "/" ~ kvm_vm__name ~ "-" ~ item["name"] ~ ".qcow2,bus=virtio") | quote }}
230:       {% endfor %}
231:       {% for item in kvm_vm__existing_additional_disks %}
232:       --disk {{ (kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] ~ "/" ~ item ~ ",bus=virtio") | quote }}
233:       {% endfor %}
234:       {% if __kvm_vm__boot_disk_created and not kvm_vm__skip_cloud_init %}
235:       --disk {{ kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] }}/{{ kvm_vm__name }}-cloud-init.iso,device=cdrom,bus=scsi,format=iso
236:       {% endif %}
237:       {% for item in kvm_vm__network_connections %}
238:       --network {{ item["network_type"] | d("network") }}={{ item["network_name"] | d("default") }},model=virtio,mac={{ item["mac"] | default(("52:54:" + ("%02d" | format(loop.index0) | string)) | community.general.random_mac(seed=inventory_hostname)) }}
239:       {% endfor %}
240:       --noautoconsole
241:       --nographics
242:       --noreboot
243:       --osinfo '{{ kvm_vm__osinfo }}'
244:       --rng /dev/urandom
245:       --serial pty
246:       --sound none
247:       --virt-type kvm
248:     ansible.builtin.command: >
249:       virt-install
250:       {% if kvm_vm__boot is defined and kvm_vm__boot | length %}
251:       --boot {{ kvm_vm__boot }}
252:       {% endif %}
253:       {% if kvm_vm__install_location is defined and kvm_vm__install_location | length %}
254:       --location {{ kvm_vm__install_location | quote }}
255:       {% if kvm_vm__install_extra_args | length %}
256:       --extra-args {{ kvm_vm__install_extra_args | quote }}
257:       {% endif %}
258:       --wait {{ kvm_vm__wait }}
259:       {% else %}
260:       --import
261:       {% endif %}
262:       --connect {{ kvm_vm__connect_url }}
263:       --name {{ kvm_vm__name }}
264:       --cpu host-model
265:       --vcpus {{ kvm_vm__vcpus }}
266:       --memory {{ kvm_vm__memory }},maxmemory={{ kvm_vm__max_memory }}
267: 
268:       {% if kvm_vm__existing_boot_disk is defined and kvm_vm__existing_boot_disk | length %}
269:       --disk {{ (kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] ~ '/' ~ kvm_vm__existing_boot_disk ~ ',bus=virtio') | quote }}
270:       {% else %}
271:       --disk {{ (kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] ~ '/' ~ kvm_vm__name ~ '-boot.qcow2,bus=virtio') | quote }}
272:       {% endif %}
273: 
274:       {% for item in kvm_vm__additional_disks %}
275:       --disk {{ (kvm_vm__pool_info_result["pools"][item["pool"] | d(kvm_vm__pool)]["path"] ~ "/" ~ kvm_vm__name ~ "-" ~ item["name"] ~ ".qcow2,bus=virtio") | quote }}
276:       {% endfor %}
277: 
278:       {% for item in kvm_vm__existing_additional_disks %}
279:       --disk {{ (kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] ~ "/" ~ item ~ ",bus=virtio") | quote }}
280:       {% endfor %}
281: 
282:       {% if __kvm_vm__boot_disk_created and not kvm_vm__skip_cloud_init %}
283:       --disk {{ kvm_vm__pool_info_result["pools"][kvm_vm__pool]["path"] }}/{{ kvm_vm__name }}-cloud-init.iso,device=cdrom,bus=scsi,format=iso
284:       --controller type=scsi,model=virtio-scsi
